  async binaryInitHelper(t) {
    if (t.rawData && t.rawData instanceof ArrayBuffer)
      return t.rawData;
    if (t.url)
      return this.$iApi.geo.layer.files.fetchFileData(t.url, t.layerType);
    throw new Error(`${t.layerType} config contains no url or invalid/missing raw data`);
  }
  /**
   * Convert an ArrayBuffer to a UTF-8 string
   *
   * @param {ArrayBuffer} input binary input
   * @returns {string} input in string form
   */
  arbToStr(t) {
    return new TextDecoder("utf-8").decode(new Uint8Array(t));
  }
